"use client"

import * as React from "react"
import { Avatar as AvatarPrimitive } from "radix-ui"

import { useInk, useMergedRef } from "@/lib/ink/react"
import {
  avatarBadgeRecipe,
  avatarCountRecipe,
  avatarFallbackRecipe,
  avatarRingRecipe,
  avatarTone,
  initials,
  type AvatarRing,
  type AvatarStatus,
  type AvatarTone,
} from "@/lib/ink/recipes/avatar-ink"
import { cn } from "@/lib/utils"

const CUT = "shadow-[0_0_0_2px_var(--ll-avatar-ring,transparent)]"

function Avatar({
  className,
  size = "default",
  ring = "ink",
  seed,
  ref,
  children,
  ...props
}: React.ComponentProps<typeof AvatarPrimitive.Root> & {
  size?: "default" | "sm" | "lg" | "xl"
  ring?: AvatarRing | "none"
  seed?: string | number
}) {
  const { hostRef, hostProps, node } = useInk({ recipe: avatarRingRecipe, params: { ring: ring === "none" ? "ink" : ring }, kind: "avatar", seed, still: true })
  const drawn = ring !== "none"
  return (
    <AvatarPrimitive.Root
      data-slot="avatar"
      data-size={size}
      ref={useMergedRef<HTMLSpanElement>(drawn ? hostRef : undefined, ref)}
      {...(drawn && node ? hostProps : {})}
      className={cn(
        "group/avatar relative isolate flex size-8 shrink-0 rounded-full select-none data-[size=lg]:size-10 data-[size=sm]:size-6 data-[size=xl]:size-14 forced-colors:outline-0!",
        CUT,
        className
      )}
      {...props}
    >
      {drawn ? node : null}
      {children}
    </AvatarPrimitive.Root>
  )
}

function AvatarImage({ className, ...props }: React.ComponentProps<typeof AvatarPrimitive.Image>) {
  return <AvatarPrimitive.Image data-slot="avatar-image" className={cn("aspect-square size-full rounded-full object-cover", className)} {...props} />
}

function AvatarFallback({
  className,
  name,
  tone,
  seed,
  children,
  ref,
  ...props
}: React.ComponentProps<typeof AvatarPrimitive.Fallback> & {
  name?: string
  tone?: AvatarTone
  seed?: string | number
}) {
  const basis = name ?? (typeof children === "string" ? children : "")
  const t = tone ?? avatarTone(basis)
  const { hostRef, hostProps, node } = useInk({ recipe: avatarFallbackRecipe, params: { tone: t }, kind: "disc", seed: seed ?? (basis || undefined), still: true })
  return (
    <AvatarPrimitive.Fallback
      data-slot="avatar-fallback"
      data-tone={t}
      ref={useMergedRef<HTMLSpanElement>(hostRef, ref)}
      {...(node ? hostProps : {})}
      className={cn(
        "relative isolate flex size-full items-center justify-center rounded-full font-hand text-sm font-bold text-ink forced-colors:outline-0! group-data-[size=sm]/avatar:text-xs group-data-[size=lg]/avatar:text-base group-data-[size=xl]/avatar:text-xl",
        className
      )}
      {...props}
    >
      {node}
      {name && children === undefined ? (
        <>
          <span aria-hidden="true">{initials(name)}</span>
          <span className="sr-only">{name}</span>
        </>
      ) : (
        children
      )}
    </AvatarPrimitive.Fallback>
  )
}

function AvatarBadge({
  className,
  status = "marker",
  seed,
  ref,
  children,
  ...props
}: React.ComponentProps<"span"> & {
  status?: AvatarStatus
  seed?: string | number
}) {
  const { hostRef, hostProps, node } = useInk({ recipe: avatarBadgeRecipe, params: { status }, kind: "dot", seed, still: true })
  return (
    <span
      data-slot="avatar-badge"
      data-status={status}
      ref={useMergedRef<HTMLSpanElement>(hostRef, ref)}
      {...(node ? hostProps : {})}
      className={cn(
        "absolute end-0 bottom-0 z-10 isolate inline-flex items-center justify-center rounded-full text-ink select-none forced-colors:outline-0!",
        "group-data-[size=sm]/avatar:size-2 group-data-[size=sm]/avatar:[&>svg]:hidden",
        "group-data-[size=default]/avatar:size-2.5 group-data-[size=default]/avatar:[&>svg:not(.absolute)]:size-2",
        "group-data-[size=lg]/avatar:size-3 group-data-[size=lg]/avatar:[&>svg:not(.absolute)]:size-2",
        "group-data-[size=xl]/avatar:size-3.5 group-data-[size=xl]/avatar:[&>svg:not(.absolute)]:size-2.5",
        className
      )}
      {...props}
    >
      {node}
      {children}
    </span>
  )
}

function AvatarGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="avatar-group"
      className={cn(
        "group/avatar-group flex items-center *:data-[slot=avatar]:[--ll-avatar-ring:var(--ll-avatar-group-ring,var(--card))] [&>*+*]:-ms-1.5 has-data-[size=sm]:[&>*+*]:-ms-1 has-data-[size=lg]:[&>*+*]:-ms-2 has-data-[size=xl]:[&>*+*]:-ms-3.5",
        className
      )}
      {...props}
    />
  )
}

function AvatarGroupCount({ className, seed, ref, children, ...props }: React.ComponentProps<"div"> & { seed?: string | number }) {
  const { hostRef, hostProps, node } = useInk({ recipe: avatarCountRecipe, params: {}, kind: "disc", seed, still: true })
  return (
    <div
      data-slot="avatar-group-count"
      ref={useMergedRef<HTMLDivElement>(hostRef, ref)}
      {...(node ? hostProps : {})}
      className={cn(
        "relative isolate flex size-8 shrink-0 items-center justify-center rounded-full font-hand text-sm font-bold text-ink-soft [--ll-avatar-ring:var(--ll-avatar-group-ring,var(--card))] forced-colors:outline-0!",
        CUT,
        "group-has-data-[size=lg]/avatar-group:size-10 group-has-data-[size=sm]/avatar-group:size-6 group-has-data-[size=xl]/avatar-group:size-14 group-has-data-[size=sm]/avatar-group:text-xs [&>svg:not(.absolute)]:size-4 group-has-data-[size=lg]/avatar-group:[&>svg:not(.absolute)]:size-5 group-has-data-[size=sm]/avatar-group:[&>svg:not(.absolute)]:size-3",
        className
      )}
      {...props}
    >
      {node}
      {children}
    </div>
  )
}

export { Avatar, AvatarImage, AvatarFallback, AvatarBadge, AvatarGroup, AvatarGroupCount }

import { blobFill, wash } from '@/lib/ink/fills'
import { ellipsePoly } from '@/lib/ink/geom'
import { defineRecipe } from '@/lib/ink/recipes'
import { clamp, hashSeed } from '@/lib/ink/rng'
import { dashedBox, loop } from '@/lib/ink/shapes'
import type { PaintKey } from '@/lib/ink/paint'
import type { PenName } from '@/lib/ink/types'

export const AVATAR_TONES = ['tomato', 'tangerine', 'lemon', 'grass', 'teal', 'sky', 'grape', 'bubblegum'] as const
export type AvatarTone = (typeof AVATAR_TONES)[number]

export function avatarTone(name: string): AvatarTone {
  const h = hashSeed(name.trim().toLowerCase())
  return AVATAR_TONES[Math.imul(h ^ (h >>> 15), 0x2c1b3c6d) >>> 29]
}

export function initials(name: string): string {
  const words = name.trim().split(/\s+/).filter(Boolean)
  if (!words.length) return ''
  const first = Array.from(words[0])[0] ?? ""
  const last = words.length > 1 ? (Array.from(words[words.length - 1])[0] ?? "") : ""
  return (first + last).toUpperCase()
}

export type AvatarRing = 'ink' | 'you' | 'marker'

const RING_PEN: Record<AvatarRing, PenName> = { ink: 'ink.fine', you: 'blue.fine', marker: 'terracotta' }

export const avatarRingRecipe = defineRecipe<{ ring: AvatarRing }>({
  id: 'avatar-ring',
  kind: 'avatar',
  layers: ['rest'],
  pad: 8,
  draw(ink, { w, h }, { ring }, ctx) {
    const cx = w / 2, cy = h / 2
    const s = Math.min(w, h)
    ink.layer('rest', () => {
      if (ring === 'marker') {
        loop(ink, cx, cy, w / 2 + 1, h / 2 + 1, { pen: 'terracotta', turns: 1.06, opts: { width: clamp(s / 60, 0.28, 0.5), alpha: 0.8 } })
        return
      }
      loop(ink, cx, cy, w / 2 + 1.6, h / 2 + 1.6, { pen: ctx.calm ? 'pencil.fine' : RING_PEN[ring], turns: ctx.calm ? 1.02 : 1.09, opts: { width: clamp(s / 34, 0.85, 1.35) } })
    })
  },
})

export const avatarFallbackRecipe = defineRecipe<{ tone: AvatarTone }>({
  id: 'avatar-fallback',
  kind: 'disc',
  layers: ['rest'],
  pad: 6,
  draw(ink, { w, h }, { tone }, ctx) {
    const cx = w / 2, cy = h / 2
    const body = ellipsePoly(cx, cy, w / 2 - 0.5, h / 2 - 0.5, 28)
    ink.layer('rest', () => {
      ink.poly('under', body, 'slip', 0.95)
      const key = tone as PaintKey
      if (ctx.calm) wash(ink, body, key, { alpha: 0.5 })
      else ink.part('fill', () => blobFill(ink, body, key, { alpha: 0.62, mis: clamp(Math.min(w, h) * 0.07, 0.8, 2.4) }))
    })
  },
})

export type AvatarStatus = 'online' | 'away' | 'busy' | 'offline' | 'marker'
const STATUS_KEY: Record<AvatarStatus, PaintKey> = { online: 'grass', away: 'tangerine', busy: 'tomato', offline: 'pencil-mark', marker: 'marker' }

export const avatarBadgeRecipe = defineRecipe<{ status: AvatarStatus }>({
  id: 'avatar-badge',
  kind: 'dot',
  layers: ['rest'],
  pad: 4,
  draw(ink, { w, h }, { status }, ctx) {
    const cx = w / 2, cy = h / 2
    ink.layer('rest', () => {
      ink.poly('under', ellipsePoly(cx, cy, w / 2 + 0.5, h / 2 + 0.5, 16), 'slip', 0.95)
      blobFill(ink, ellipsePoly(cx, cy, w / 2 - 0.4, h / 2 - 0.4, 16), STATUS_KEY[status], { alpha: status === 'offline' ? 0.55 : 0.92, mis: ctx.calm ? false : 0.5, rough: 0.4 })
      if (!ctx.calm) loop(ink, cx, cy, w / 2 + 0.2, h / 2 + 0.2, { pen: 'ink.fine', turns: 1.1, opts: { width: 0.85 } })
    })
  },
})

export const avatarCountRecipe = defineRecipe<Record<string, never>>({
  id: 'avatar-count',
  kind: 'disc',
  layers: ['rest'],
  pad: 6,
  draw(ink, { w, h }, _p, ctx) {
    const body = ellipsePoly(w / 2, h / 2, w / 2 - 1, h / 2 - 1, 28)
    ink.layer('rest', () => {
      ink.poly('under', body, 'slip', 0.95)
      wash(ink, body, 'paper-shade', { alpha: 0.9 })
      dashedBox(ink, 0.5, 0.5, w - 1, h - 1, { r: Math.min(w, h) / 2, pen: ctx.calm ? 'pencil.fine' : 'pencil', dash: Math.max(4, Math.min(w, h) * 0.2) })
    })
  },
})
